package in.tucor.api.auth;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="registration_profiles") public class RegistrationProfile {
@Id @Column(name="user_id") public UUID userId; @Column(name="business_name",nullable=false) public String businessName; @Column(name="business_type",nullable=false) public String businessType; @Column(name="gst_number",nullable=false) public String gstNumber; @Column(name="registration_number") public String registrationNumber; @Column(nullable=false) public String address; @Column(nullable=false) public String city; @Column(nullable=false) public String state; @Column(nullable=false) public String pincode; @Column(name="estimated_volume_monthly") public String estimatedVolumeMonthly; @Column(name="full_name",nullable=false) public String fullName; @Column(nullable=false) public String phone; @Column(name="created_at",nullable=false) public Instant createdAt; @Column(name="updated_at",nullable=false) public Instant updatedAt;
@PrePersist void create(){createdAt=updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();}
}